from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    depth = 0
    start = 0
    for i, ch in enumerate(paren_string):
        if ch == ' ':
            continue
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                result.append(paren_string[start:i + 1].replace(' ', ''))
    return result
